-- =============================================================================
-- bio-pipelines/base/docker_seed.sql
-- Self-contained bootstrap schema & curated seed dataset for Docker testing
-- =============================================================================
CREATE EXTENSION IF NOT EXISTS pg_bio CASCADE;

CREATE TABLE IF NOT EXISTS proteins (
    uniprot_id VARCHAR(20) PRIMARY KEY,
    name TEXT,
    sequence TEXT,
    embedding vector(1280)
);
-- A table from an older seed has no embedding column; add it in place.
ALTER TABLE proteins ADD COLUMN IF NOT EXISTS embedding vector(1280);

CREATE TABLE IF NOT EXISTS orphan_discoveries (
    id SERIAL PRIMARY KEY,
    family_name TEXT NOT NULL,
    bait_id VARCHAR(50) NOT NULL,
    bait_organism TEXT,
    orphan_id VARCHAR(50) NOT NULL,
    orphan_organism TEXT,
    vector_distance REAL NOT NULL,
    discovered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    status VARCHAR(50) DEFAULT 'Explored',
    confidence_score FLOAT8,
    tm_score FLOAT8,
    interpro_domains TEXT[],
    nucleotide_accession VARCHAR(50),
    neighborhood_sequence TEXT,
    seq_identity_pct FLOAT8,
    twilight_score FLOAT8,
    chaperone_lineage_id TEXT,
    chaperone_score FLOAT8,
    sc_rmsd FLOAT8,
    mean_rasa FLOAT8,
    buns_count INT,
    hbond_count INT,
    surf_hydro_frac FLOAT8,
    rf_range_iou FLOAT8,
    rf_giou_loss FLOAT8,
    rf_substrate_match BOOLEAN,
    rf_substrate_props_matched INT,
    rf_arom_prob FLOAT8,
    rf_score FLOAT8
);

CREATE TABLE IF NOT EXISTS swarm_checkpoint (
    id INT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
    pass_ring INT DEFAULT 3 NOT NULL,
    max_out_degree INT DEFAULT 35 NOT NULL,
    last_seed_uid TEXT DEFAULT '0' NOT NULL,
    last_3d_backfill_id BIGINT DEFAULT 390667 NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    last_tpp_backfill_id BIGINT DEFAULT 1 NOT NULL
);

CREATE TABLE IF NOT EXISTS swarm_comparison_cache (
    id1 TEXT NOT NULL,
    id2 TEXT NOT NULL,
    schema_version INT DEFAULT 3 NOT NULL,
    metrics_payload JSONB NOT NULL,
    pdb1_path TEXT,
    pdb2_aligned_path TEXT,
    updated_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    PRIMARY KEY (id1, id2)
);

CREATE TABLE IF NOT EXISTS swarm_concurrency_benchmarks (
    workers INT PRIMARY KEY,
    avg_step_ms FLOAT8 NOT NULL,
    p95_step_ms FLOAT8 NOT NULL,
    steps_per_sec FLOAT8 NOT NULL,
    edges_per_sec FLOAT8 NOT NULL,
    parallel_efficiency_pct FLOAT8 NOT NULL,
    regime_note TEXT NOT NULL,
    calibrated_at TIMESTAMPTZ DEFAULT NOW() NOT NULL
);

CREATE TABLE IF NOT EXISTS swarm_telemetry_log (
    id BIGSERIAL PRIMARY KEY,
    recorded_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    power_mode TEXT NOT NULL,
    active_workers INT NOT NULL,
    hid_idle_sec FLOAT8 NOT NULL,
    load_avg_1m FLOAT8 NOT NULL,
    steps_completed INT NOT NULL,
    edges_discovered INT NOT NULL,
    pockets_3d_indexed INT NOT NULL,
    rf_pairs_scored INT NOT NULL,
    avg_step_ms FLOAT8 NOT NULL,
    p95_step_ms FLOAT8 NOT NULL,
    steps_per_sec FLOAT8 NOT NULL,
    edges_per_sec FLOAT8 NOT NULL,
    total_graph_edges BIGINT NOT NULL,
    total_3d_rf_edges BIGINT NOT NULL,
    tpp_cascades_mapped INT DEFAULT 0 NOT NULL,
    total_tpp_cascades BIGINT DEFAULT 0 NOT NULL
);

CREATE TABLE IF NOT EXISTS swarm_tpp_knockout_cascades (
    id BIGSERIAL PRIMARY KEY,
    edge_id BIGINT NOT NULL,
    microprotein_id VARCHAR(50) NOT NULL,
    microprotein_org TEXT NOT NULL,
    microprotein_len INT NOT NULL,
    microprotein_desc TEXT NOT NULL,
    partner_complex_id VARCHAR(50) NOT NULL,
    partner_org TEXT NOT NULL,
    partner_len INT NOT NULL,
    partner_desc TEXT NOT NULL,
    family_name TEXT NOT NULL,
    vector_distance FLOAT8 NOT NULL,
    interface_comp FLOAT8 NOT NULL,
    rf_range_iou FLOAT8,
    tm_wt_c FLOAT8 NOT NULL,
    tm_ko_c FLOAT8 NOT NULL,
    delta_tm_c FLOAT8 NOT NULL,
    tpca_decoherence FLOAT8 NOT NULL,
    chaperone_sink_load FLOAT8 NOT NULL,
    allosteric_spillover_targets INT DEFAULT 0 NOT NULL,
    allosteric_delta_tm_c FLOAT8 DEFAULT 0.0 NOT NULL,
    cascade_impact_score FLOAT8 NOT NULL,
    disruption_class TEXT NOT NULL,
    wt_curve_code BIGINT NOT NULL,
    ko_curve_code BIGINT NOT NULL,
    discovered_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    t_opt_wt_c FLOAT8,
    t_opt_ko_c FLOAT8,
    delta_t_opt_c FLOAT8,
    catalytic_flux_gain_x FLOAT8,
    activity_wt_code BIGINT,
    activity_ko_code BIGINT,
    micro_gravy FLOAT8,
    micro_pi FLOAT8,
    partner_pi FLOAT8,
    staple_mechanism TEXT,
    UNIQUE (microprotein_id, partner_complex_id)
);

CREATE TABLE IF NOT EXISTS swarm_pocket_ranges (
    uniprot_id TEXT PRIMARY KEY,
    pocket_cx FLOAT8 NOT NULL,
    pocket_cy FLOAT8 NOT NULL,
    pocket_cz FLOAT8 NOT NULL,
    pocket_radius FLOAT8 DEFAULT 10.0 NOT NULL,
    pdb_path TEXT,
    mw_range NUMRANGE NOT NULL,
    logp_range NUMRANGE NOT NULL,
    hbd_range NUMRANGE NOT NULL,
    hba_range NUMRANGE NOT NULL,
    tpsa_range NUMRANGE NOT NULL,
    rot_range NUMRANGE NOT NULL,
    charge_range NUMRANGE NOT NULL,
    arom_range NUMRANGE NOT NULL,
    fsp3_range NUMRANGE NOT NULL,
    mw_min FLOAT8 NOT NULL,
    mw_max FLOAT8 NOT NULL,
    logp_min FLOAT8 NOT NULL,
    logp_max FLOAT8 NOT NULL,
    hbd_min FLOAT8 NOT NULL,
    hbd_max FLOAT8 NOT NULL,
    hba_min FLOAT8 NOT NULL,
    hba_max FLOAT8 NOT NULL,
    tpsa_min FLOAT8 NOT NULL,
    tpsa_max FLOAT8 NOT NULL,
    rot_min FLOAT8 NOT NULL,
    rot_max FLOAT8 NOT NULL,
    charge_min FLOAT8 NOT NULL,
    charge_max FLOAT8 NOT NULL,
    arom_min FLOAT8 NOT NULL,
    arom_max FLOAT8 NOT NULL,
    fsp3_min FLOAT8 NOT NULL,
    fsp3_max FLOAT8 NOT NULL,
    aromatic_probability FLOAT8 NOT NULL
);


-- The column the code reads is of no use empty: p1.embedding <=> p2.embedding
-- is NULL, and the HNSW neighbour searches in swarm_discovery.py return
-- nothing, so the swarm never finds a frontier node to expand.
-- get_esm_embedding is immutable and parallel safe, so the seed can fill it
-- here: 1412 rows in about 65 ms.
UPDATE proteins
   SET embedding = get_esm_embedding(sequence)::vector
 WHERE embedding IS NULL
   AND sequence IS NOT NULL;
